/**
 * 本物の符号化器が吐いた画像（縦横が分かっているもの）。
 *
 * 縦横の読み取りを、手で組んだヘッダで試すと**自分の思い込みを自分で
 * 確かめる**ことにしかならない。ここに置くのは Chromium の canvas が
 * 実際に書き出したバイト列（PNG・JPEG・WebP）で、素の VP8 / VP8L は
 * その入れ物（VP8X）から中身の1チャンクを取り出して組み直したもの。
 * GIF だけは canvas から出せないので組み立てたが、**7枚とも Chromium
 * に読ませて 40x24（縦は 24x40）で表示されることを確かめてある**。
 *
 * 40x24 と 24x40 を両方置いてあるのは、縦横を取り違えた読み取り
 * （JPEG は高さが先に来る）が正方形の絵では露見しないため。
 */

/** base64 を ArrayBuffer へ。テストから実物と同じ形で渡すため。 */
function bytes(base64: string): ArrayBuffer {
  const bin = atob(base64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}

